#include "coordinate_point_common.hpp"
struct TP {int n,L;LD rate,Z;vector<LD>a,w;vector<vector<pair<int,LD>>>cdf;};
TP prepTree(const OG&g,int L,LD rate){TP p;p.L=L;p.n=L+1;p.rate=rate;int full=(1<<p.n)-1;p.a.resize(full+1);p.w.resize(full+1);p.cdf.resize(full+1);uint64_t inside[256]={};for(int s=1;s<=full;s++){int k=0;for(int i=0;i<p.n;i++)for(int j=i+1;j<p.n;j++,k++)if((s>>i&1)&&(s>>j&1))inside[s]|=1ULL<<(2*k);}
 for(int s=1;s<=full;s++){int v=__builtin_popcount(s);if(v==1){p.w[s]=1;continue;}int em=0;for(auto&t:g.g.terms){int e=__builtin_popcountll(t.key&inside[s])+2*__builtin_popcountll((t.key>>1)&inside[s]);em=max(em,e);}LD pow=v-1-em/2.L;if(pow<0)throw runtime_error("power cluster in free graph");p.a[s]=s==full?1:rate*max(.5L,pow);int bit=s&-s;LD sum=0;for(int u=(s-1)&s;u;u=(u-1)&s)if(u&bit){int v=s^u;sum+=2*p.w[u]*p.w[v];p.cdf[s].push_back({u,sum});}p.w[s]=sum/p.a[s];}p.Z=p.w[full];return p;}
struct TreeSample {int n,L,ng,nn,leafn;int masks[28],gapnodes[7],parents[7],sizes[7],clusters[7],order[8];LD lt[7],alpha[7];};
TreeSample drawTree(const TP&p,const LD*u){TreeSample t{};t.n=p.n;t.L=p.L;int ci=0;function<void(int,int)>go=[&](int s,int parent){if(!(s&(s-1))){t.order[t.leafn++]=__builtin_ctz(s);return;}int id=t.nn++;t.parents[id]=parent;t.sizes[id]=__builtin_popcount(s);t.clusters[id]=s;LD v=u[ci++];if(id){t.alpha[id]=p.a[s];t.lt[id]=logl(u[p.L+id-1])/t.alpha[id];}else{t.alpha[id]=1;t.lt[id]=0;}bool flip=v>.5L;v=flip?2*v-1:2*v;LD z=v*p.cdf[s].back().second;auto it=lower_bound(p.cdf[s].begin(),p.cdf[s].end(),z,[](auto&a,LD b){return a.second<b;});if(it==p.cdf[s].end())--it;int A=it->first,B=s^A;if(flip)swap(A,B);go(A,id);t.gapnodes[t.ng++]=id;go(B,id);};go((1<<p.n)-1,-1);int pos[8];for(int i=0;i<p.n;i++)pos[t.order[i]]=i;int k=0;for(int i=0;i<p.n;i++)for(int j=i+1;j<p.n;j++){int lo=min(pos[i],pos[j]),hi=max(pos[i],pos[j]);t.masks[k++]=((1<<hi)-1)^((1<<lo)-1);}return t;}
template<class T>array<T,7> treePoint(const OG&g,int L,int K,const TreeSample&s,LD*rat){T scales[7],gap[7];scales[0]=1;T weight=1;for(int j=1;j<L;j++){T tt=expt(T(s.lt[j]));scales[j]=scales[s.parents[j]]*tt;weight*=expt(T((s.sizes[j]-1-s.alpha[j])*s.lt[j]));}for(int j=0;j<L;j++)gap[j]=scales[s.gapnodes[j]];int sz=1<<L;T dist[128]={},iv[28],logs[28];for(int mask=1;mask<sz;mask++){int bit=__builtin_ctz(mask);dist[mask]=dist[mask^(1<<bit)]+gap[bit];}int NE=L*(L+1)/2;for(int k=0;k<NE;k++){iv[k]=1/sqrtt(dist[s.masks[k]]);logs[k]=logt(dist[s.masks[k]])/2;}array<T,7>sum{};T absum[7]={};for(auto&t:g.terms){T H=0,R=0,base=1,lv=0;for(auto&e:t.e){int k=e[0],m=e[1];H+=m*dist[s.masks[k]];R+=e[2]*dist[s.masks[k]];T v=iv[k];if(m==1)base*=v;else if(m==2)base*=v*v;else base*=v*v*v;lv+=m*logs[k];}if(R==0)continue;base*=R/H;lv-=L*logt(H);for(int j=0;j<=K;j++){sum[j]+=base;absum[j]+=base<0?-base:base;base*=lv/(j+1);}}if(rat){*rat=1;for(int j=0;j<=K;j++)if(absum[j]>0)*rat=min(*rat,abs((LD)(sum[j]/absum[j])));}for(int j=0;j<=K;j++)sum[j]*=weight;return sum;}
int main(int argc,char**argv){try{if(argc<9){cerr<<"root L points reps seed net output rate [select] [counts]\n";return 1;}string root=argv[1];int L=stoi(argv[2]),N=stoi(argv[3]),B=stoi(argv[4]);uint64_t seed=stoull(argv[5]);string netfile=argv[6],output=argv[7];LD rate=stold(argv[8]);string sel=argc>9?argv[9]:"free";int Li;auto g0=load(root+"/L"+to_string(L)+"_coord.txt",Li);vector<OG>gs;int NE=L*(L+1)/2;for(auto&g:g0){OG og;og.g=g;for(auto&t:g.terms){OptTerm tt;for(int k=0;k<NE;k++)if(t.m[k])tt.e.push_back({k,t.m[k],t.co[k]});og.terms.push_back(tt);}gs.push_back(move(og));}vector<int>counts(gs.size(),N);if(argc>10){ifstream cf(argv[10]);int nn;cf>>nn;if(nn!=(int)gs.size())throw runtime_error("counts mismatch");for(int i=0;i<nn;i++){int id,k;cf>>id>>k;counts[id]=k;}if(!cf)throw runtime_error("counts file");}vector<LD>gam(7);ifstream gf(root+"/cgamma_L"+to_string(L)+".txt");for(auto&x:gam)gf>>x;
 vector<TP>props(gs.size());for(int i=0;i<(int)gs.size();i++){auto&g=gs[i];if(g.g.power||g.terms.empty())counts[i]=0;if(L==7&&abs(3*g.g.wb-g.g.wa)<1e-17L)counts[i]=0;if(sel=="primitive"&&!g.g.primitive)counts[i]=0;if(sel=="nonprimitive"&&g.g.primitive)counts[i]=0;if(counts[i])props[i]=prepTree(g,L,rate);}
 ifstream nf(netfile,ios::binary);uint32_t hdr[3];nf.read((char*)hdr,12);int dim=hdr[1],bits=hdr[2];if(hdr[0]!=(uint32_t)B||dim<2*L-1)throw runtime_error("net dims");vector<uint64_t>mat((size_t)B*dim*bits);nf.read((char*)mat.data(),mat.size()*8);if(!nf)throw runtime_error("netfile");LD sign=(L%2)?1:-1;int K=7-L;vector<vector<LD>>batches(B,vector<LD>(14));vector<vector<array<LD,14>>>per(B,vector<array<LD,14>>(gs.size()));vector<long long>quads(B),mps(B);double start=omp_get_wtime();
 #pragma omp parallel for num_threads(4) schedule(dynamic)
 for(int ib=0;ib<B;ib++){const uint64_t*dir=&mat[(size_t)ib*dim*bits];for(int gi=0;gi<(int)gs.size();gi++){auto&g=gs[gi];int NN=counts[gi];if(!NN)continue;mt19937_64 rng(seed+0x9e3779b97f4a7c15ULL*(ib+1)+0xbf58476d1ce4e5b9ULL*(gi+1));vector<uint64_t>state(dim);for(auto&v:state)v=rng()&((1ULL<<bits)-1);array<LD,7>tot{};for(int it=0;it<NN;it++){if(it){int z=__builtin_ctz(it);for(int j=0;j<dim;j++)state[j]^=dir[j*bits+z];}LD uu[16];for(int j=0;j<dim;j++)uu[j]=((LD)state[j]+.5L)/powl(2.L,bits);auto s=drawTree(props[gi],uu);LD ratio;auto val=treePoint<LD>(g,L,K,s,&ratio);if(ratio<1e-7L){quads[ib]++;auto q=treePoint<__float128>(g,L,K,s,&ratio);for(int k=0;k<=K;k++)val[k]=(LD)q[k];if(ratio<1e-24L){mps[ib]++;auto m=treePoint<MP>(g,L,K,s,nullptr);for(int k=0;k<=K;k++)val[k]=(LD)m[k];}}for(int j=0;j<=K;j++)tot[j]+=val[j]/NN;}
 for(int k=0;k<=K;k++){LD val=0;for(int j=0;j<=k;j++)val+=tot[j]*gam[k-j];int i=L-1+k;per[ib][gi][i]=sign*props[gi].Z*g.g.wa*val;per[ib][gi][7+i]=sign*props[gi].Z*g.g.wb*val;batches[ib][i]+=per[ib][gi][i];batches[ib][7+i]+=per[ib][gi][7+i];}}
 #pragma omp critical
 cerr<<"rep "<<ib<<" seconds "<<omp_get_wtime()-start<<" b0 "<<setprecision(16)<<batches[ib][L-1]<<" c0 "<<batches[ib][7+L-1]<<" q "<<quads[ib]<<" mp "<<mps[ib]<<"\n";}
 ofstream out(output);out<<setprecision(24)<<"{\"L\":"<<L<<",\"N\":"<<N<<",\"replicates\":"<<B<<",\"seed\":"<<seed<<",\"rate\":"<<rate<<",\"selection\":\""<<sel<<"\",\"method\":\"binary_cluster_tree\",\"seconds\":"<<omp_get_wtime()-start<<",\"batches\":[";for(int ib=0;ib<B;ib++){if(ib)out<<',';out<<'[';for(int j=0;j<14;j++){if(j)out<<',';out<<batches[ib][j];}out<<']';}out<<"],\"graph_batches\":[";for(int ib=0;ib<B;ib++){if(ib)out<<',';out<<'[';for(int gi=0;gi<(int)gs.size();gi++){if(gi)out<<',';out<<'[';for(int j=0;j<14;j++){if(j)out<<',';out<<per[ib][gi][j];}out<<']';}out<<']';}out<<"],\"counts\":[";for(int gi=0;gi<(int)counts.size();gi++){if(gi)out<<',';out<<counts[gi];}out<<"],\"quads\":[";for(int ib=0;ib<B;ib++){if(ib)out<<',';out<<quads[ib];}out<<"],\"mps\":[";for(int ib=0;ib<B;ib++){if(ib)out<<',';out<<mps[ib];}out<<"]}\n";
 }catch(exception&e){cerr<<e.what()<<'\n';return 2;}}
